        .faq-section{
            max-width:1200px;
            margin:50px auto;
            padding:40px 20px;
            position:relative;
            background-color: rgba(0, 0, 0, 0.1);
            backdrop-filter: blur(25px);
            border-radius: 20px;
            }

        .faq-section h2{
            text-align:center;
            font-size:34px;font-weight:700;
            margin-bottom:50px;
            background: gold;
            -webkit-background-clip:text;
            -webkit-text-fill-color:transparent;
            background-clip:text;
            font-family:"Poppins",sans-serif;letter-spacing:1px
        }

        .faq-container{
            display:flex;
            flex-direction:column;
            gap:25px
        }

        .faq-item{
            background:linear-gradient(145deg,#0a0a0a,#1a1a1a);
            border:2px solid gold;
            border-radius:60px;overflow:hidden;
            transition:all .4s ease;box-shadow:0 5px 20px rgba(0,0,0,0.5)
        }

        .faq-item:hover{
            border-color:gold;
            transform:translateX(10px);
            box-shadow:0 12px 35px rgba(253, 4, 4, 0.25)
        }

        .faq-question{width:100%;
            padding:28px 35px;background:transparent;
            color:#ffffff;
            font-size:18px;
            font-weight:600;
            text-align:left;
            border:none;cursor:pointer;
            display:flex;
            justify-content:space-between;
            align-items:center;
            font-family:"Poppins",sans-serif;
            transition:all .3s ease
        }

        .faq-question:hover{
            color:gold
        }

        .faq-question::after{
            content:'+';
            font-size:32px;
            font-weight:300;
            transition:all .4s ease;
            color:gold;
            width:40px;
            height:40px;
            display:flex;
            align-items:center;
            justify-content:center;
            border:2px solid red;border-radius:50%;
            background:rgba(0, 0, 0, 0.1)
        }

        .faq-item.active .faq-question::after{
            transform:rotate(135deg);
            background:linear-gradient(135deg,darkred,red);
            color:#000;border-color:transparent
        }

        .faq-answer{
            max-height:0;
            overflow:hidden;
            transition:max-height .5s ease,padding .5s ease;
            background:linear-gradient(180deg,rgba(253,228,4,0.05),transparent);
            padding:0 35px
        }

        .faq-item.active .faq-answer{
            max-height:800px;padding:30px 35px;
            border-top:1px solid rgba(253, 4, 4, 0.3)
        }

        .faq-answer p{
            color:#e0e0e0;
            font-size:16px;
            line-height:2;
            margin:0;
            font-family:"Poppins",sans-serif
        }

        @media
            (max-width:768px)
        {

        .faq-section
            {padding:30px 15px}

        .faq-section h2
            {font-size:26px}

        .faq-question
            {font-size:16px;
            padding:22px 25px}

        .faq-question::after
            {width:35px;
            height:35px;
            font-size:28px}

        .faq-answer
            {padding:0 25px}

        .faq-item.active .faq-answer
            {padding:25px}

        .faq-item:hover
            {transform:translateX(5px)}
            }
